-- A Solution Commerce / PostgreSQL (Supabase)
create extension if not exists pgcrypto;
create table if not exists public.store_settings(id uuid primary key default gen_random_uuid(), store_name text not null default 'A Solution', currency text not null default 'SAR', vat_rate numeric(5,4) not null default .15, locale_default text not null default 'en', updated_at timestamptz not null default now());
create table if not exists public.store_categories(id uuid primary key default gen_random_uuid(), slug text unique not null, name_en text not null, name_ar text not null, active boolean not null default true, sort_order int not null default 0);
create table if not exists public.store_products(id uuid primary key default gen_random_uuid(), slug text unique not null, sku text unique, type text not null default 'service' check(type in('service','physical','digital')), category_id uuid references public.store_categories(id) on delete set null, name_en text not null, name_ar text not null, description_en text not null default '', description_ar text not null default '', price numeric(12,2) not null check(price>=0), compare_at_price numeric(12,2), active boolean not null default true, featured boolean not null default false, inventory_qty int, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.product_variants(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.store_products(id) on delete cascade, sku text unique, name_en text not null, name_ar text not null, price numeric(12,2), inventory_qty int, active boolean not null default true);
create table if not exists public.customers(id uuid primary key default gen_random_uuid(), auth_user_id uuid unique references auth.users(id) on delete set null, email text, phone text, name text, company text, locale text default 'en', source text, tags text[] not null default '{}', lifetime_value numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table if not exists public.customer_addresses(id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id) on delete cascade, label text, city text not null, address_line text, country text not null default 'SA', is_default boolean not null default false);
create table if not exists public.customer_activities(id uuid primary key default gen_random_uuid(), customer_id uuid references public.customers(id) on delete cascade, activity_type text not null, note text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.carts(id uuid primary key default gen_random_uuid(), customer_id uuid references public.customers(id) on delete set null, session_key text unique, status text not null default 'active', currency text not null default 'SAR', updated_at timestamptz not null default now());
create table if not exists public.cart_items(id uuid primary key default gen_random_uuid(), cart_id uuid not null references public.carts(id) on delete cascade, product_id uuid not null references public.store_products(id), variant_id uuid references public.product_variants(id), quantity int not null check(quantity>0), unique(cart_id,product_id,variant_id));
create table if not exists public.coupons(id uuid primary key default gen_random_uuid(), code text unique not null, kind text not null check(kind in('fixed','percent')), value numeric(12,2) not null check(value>0), starts_at timestamptz, ends_at timestamptz, max_uses int, uses int not null default 0, active boolean not null default true);
create table if not exists public.orders(id uuid primary key default gen_random_uuid(), order_number text unique not null, customer_id uuid references public.customers(id), email text not null, phone text, name text not null, company text, city text, currency text not null default 'SAR', subtotal numeric(12,2) not null, discount numeric(12,2) not null default 0, vat numeric(12,2) not null default 0, shipping numeric(12,2) not null default 0, total numeric(12,2) not null, payment_status text not null default 'unpaid' check(payment_status in('unpaid','pending','paid','partially_refunded','refunded','failed')), fulfillment_status text not null default 'unfulfilled' check(fulfillment_status in('unfulfilled','processing','fulfilled','cancelled','returned')), notes text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.store_products(id), variant_id uuid references public.product_variants(id), name text not null, sku text, unit_price numeric(12,2) not null, quantity int not null check(quantity>0), line_total numeric(12,2) not null);
create table if not exists public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, provider text not null, provider_reference text, amount numeric(12,2) not null, status text not null, idempotency_key text unique, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.shipments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, provider text, tracking_number text, status text not null default 'pending', shipped_at timestamptz, delivered_at timestamptz);
create table if not exists public.returns(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), status text not null default 'requested', reason text, amount numeric(12,2), created_at timestamptz not null default now());
create table if not exists public.refunds(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), payment_id uuid references public.payments(id), amount numeric(12,2) not null check(amount>0), reason text, status text not null default 'pending', created_at timestamptz not null default now());
create table if not exists public.opportunities(id uuid primary key default gen_random_uuid(), customer_id uuid references public.customers(id), title text not null, value numeric(12,2) not null default 0, stage text not null default 'lead', owner_id uuid references auth.users(id), next_follow_up timestamptz, created_at timestamptz not null default now());
create table if not exists public.commerce_tasks(id uuid primary key default gen_random_uuid(), title text not null, customer_id uuid references public.customers(id), order_id uuid references public.orders(id), assigned_to uuid references auth.users(id), status text not null default 'open', due_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(), name text not null, source text, medium text, campaign text, starts_at timestamptz, ends_at timestamptz, budget numeric(12,2), active boolean not null default true);
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.store_products(id), customer_id uuid references public.customers(id), rating int not null check(rating between 1 and 5), body text, status text not null default 'pending', created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, before_data jsonb, after_data jsonb, created_at timestamptz not null default now());
create index if not exists idx_store_products_category on public.store_products(category_id,active);
create index if not exists idx_orders_customer_created on public.orders(customer_id,created_at desc);
create index if not exists idx_orders_status on public.orders(payment_status,fulfillment_status);
create index if not exists idx_activities_customer_created on public.customer_activities(customer_id,created_at desc);
